<?php
/**
 * asset-helper.php
 *
 * Helper functions for auto cache-busted assets
 * Requires SITE constant to be defined (from config.php)
 */

// Load the assets manifest (generated by npm run build - package.json - "manifest": "node build/generate-manifest.js"
$manifest     = array();
$manifestPath = FILEPATH . '/assets-manifest.json';



if ( file_exists($manifestPath) ) {
    $manifest = json_decode(file_get_contents($manifestPath), true) ?? array();
}

function asset_url( $file ) {
    global $manifest;
    $hash = $manifest[ $file ] ?? null;
    $url  = SITE . '/' . ltrim($file, '/');
    if ( $hash ) {
        $url .= '?v=' . $hash;
    }
    return $url;
}

function asset( $file ) {
    echo asset_url($file);
}
